const crypto = require('node:crypto');

const CAPABILITIES = Object.freeze(['image', 'video', 'text']);
const MAX_PROVIDER_RESPONSE_BYTES = 64 * 1024 * 1024;

function generationError(message, code, retryable = false, details = {}) {
  return Object.assign(new Error(message), { code, retryable, details });
}

function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds) && seconds >= 0) return Math.min(60_000, Math.round(seconds * 1000));
  const timestamp = Date.parse(value);
  return Number.isFinite(timestamp) ? Math.min(60_000, Math.max(0, timestamp - Date.now())) : null;
}

function retryableStatus(status) {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

function sanitizeMetadata(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const output = {};
  for (const [key, item] of Object.entries(value)) {
    if (/token|secret|authorization|api[-_]?key|password|credential/i.test(key)) continue;
    if (typeof item === 'string' && item.length > 1024) continue;
    if (['string', 'number', 'boolean'].includes(typeof item) || item === null) output[key] = item;
  }
  return output;
}

class GenerationProviderRegistry {
  #providers = new Map();

  register(capability, provider) {
    if (!CAPABILITIES.includes(capability)) throw new TypeError(`Unsupported generation capability: ${capability}`);
    if (!provider || typeof provider.execute !== 'function') throw new TypeError('provider.execute(request, context) is required');
    const name = provider.name || 'unnamed';
    const key = `${capability}:${name}`;
    if (this.#providers.has(key)) throw new Error(`Generation provider already registered: ${key}`);
    this.#providers.set(key, Object.freeze({ ...provider, capability, name }));
    return { capability, name, model: provider.model || null };
  }

  get(capability, name = null) {
    const providers = [...this.#providers.values()].filter((provider) => provider.capability === capability);
    return name ? providers.find((provider) => provider.name === name) || null : providers[0] || null;
  }

  list() {
    return [...this.#providers.values()].map(({ capability, name, model }) => ({ capability, name, model: model || null }));
  }
}

class HttpGenerationProvider {
  constructor({ capability, name, endpoint, token = null, model = null, timeoutMs = 120_000, maxResponseBytes = MAX_PROVIDER_RESPONSE_BYTES, fetchImpl = fetch } = {}) {
    if (!CAPABILITIES.includes(capability)) throw new TypeError('capability is invalid');
    if (!name || !endpoint) throw new TypeError('name and endpoint are required');
    if (!Number.isInteger(timeoutMs) || timeoutMs < 1) throw new TypeError('timeoutMs must be positive');
    if (!Number.isInteger(maxResponseBytes) || maxResponseBytes < 1024) throw new TypeError('maxResponseBytes must be >= 1024');
    this.capability = capability;
    this.name = name;
    this.endpoint = endpoint;
    this.token = token;
    this.model = model;
    this.timeoutMs = timeoutMs;
    this.maxResponseBytes = maxResponseBytes;
    this.fetchImpl = fetchImpl;
  }

  async execute(request, context = {}) {
    if (context.signal?.aborted) throw generationError('Generation provider was cancelled', 'CANCELLED');
    const controller = new AbortController();
    const abort = () => controller.abort();
    context.signal?.addEventListener('abort', abort, { once: true });
    const timeoutMs = Math.min(this.timeoutMs, Number.isInteger(context.timeoutMs) ? context.timeoutMs : this.timeoutMs);
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    timer.unref?.();
    const startedAt = Date.now();
    try {
      const headers = { 'content-type': 'application/json', accept: 'application/json' };
      if (this.token) headers.authorization = `Bearer ${this.token}`;
      let response;
      try {
        response = await this.fetchImpl(this.endpoint, {
          method: 'POST',
          headers,
          body: JSON.stringify({ contractVersion: 'forge-generation-v1', capability: this.capability, model: this.model, request, inputVersionIds: context.inputVersionIds || [], idempotencyKey: context.idempotencyKey }),
          signal: controller.signal,
        });
      } catch (error) {
        if (context.signal?.aborted) throw generationError('Generation provider was cancelled', 'CANCELLED');
        if (error?.name === 'AbortError') throw generationError(`Generation provider timed out after ${timeoutMs}ms`, 'PROVIDER_TIMEOUT', true);
        throw generationError(`Generation provider network failure: ${error?.message || 'unknown error'}`, 'PROVIDER_UNAVAILABLE', true);
      }
      const reader = response.body?.getReader?.();
      const chunks = [];
      let bytes = 0;
      if (reader) {
        while (true) {
          if (context.signal?.aborted) throw generationError('Generation provider was cancelled', 'CANCELLED');
          const next = await reader.read();
          if (next.done) break;
          bytes += next.value.byteLength;
          if (bytes > this.maxResponseBytes) throw generationError('Generation provider response exceeded the configured limit', 'PROVIDER_RESPONSE_TOO_LARGE');
          chunks.push(Buffer.from(next.value));
        }
      } else {
        const text = await response.text();
        bytes = Buffer.byteLength(text);
        if (bytes > this.maxResponseBytes) throw generationError('Generation provider response exceeded the configured limit', 'PROVIDER_RESPONSE_TOO_LARGE');
        chunks.push(Buffer.from(text));
      }
      const raw = Buffer.concat(chunks, bytes);
      let body;
      try { body = raw.length ? JSON.parse(raw.toString('utf8')) : null; } catch { throw generationError('Generation provider returned malformed JSON', 'MALFORMED_PROVIDER_RESPONSE', response.status >= 500); }
      if (!response.ok) {
        const retryAfterMs = response.status === 429 ? parseRetryAfter(response.headers?.get?.('retry-after')) : null;
        throw generationError(`Generation provider returned HTTP ${response.status}`, response.status === 429 ? 'RATE_LIMITED' : 'PROVIDER_HTTP_ERROR', retryableStatus(response.status), { status: response.status, retryAfterMs });
      }
      return { ...body, metadata: { ...sanitizeMetadata(body?.metadata), provider: this.name, model: this.model, latencyMs: Date.now() - startedAt } };
    } finally {
      clearTimeout(timer);
      context.signal?.removeEventListener('abort', abort);
    }
  }
}

class OpenAICompatibleTextProvider extends HttpGenerationProvider {
  constructor(options = {}) { super({ ...options, capability: 'text' }); }
  async execute(request, context = {}) {
    const response = await super.execute({ ...request, messages: request.messages || [{ role: 'user', content: String(request.prompt || '') }], temperature: request.temperature ?? 0.2 }, context);
    if (response?.artifact) return response;
    const content = response?.choices?.[0]?.message?.content;
    if (typeof content !== 'string' || !content.trim()) throw generationError('OpenAI-compatible text provider returned empty content', 'MALFORMED_PROVIDER_RESPONSE');
    return { ...response, artifact: { content, mediaType: 'text/plain' } };
  }
}

